fn target_bush_v30(&self, player: &PlayerState, data: &OperationData) -> usize
// IR 은 인자승격 후 (line: LineType, team: usize, pos: i32, game: &AbstractGameWithCache, context: &GameContext) 로 특수화돼 있다.
// 아래 피호출자는 전부 인라인돼 본문에 call 이 남지 않았다:
//   AbstractGameWithCache::tower            (simulation.rs:1822-1826)
//   Option::or / is_none / is_some / unwrap (core/option.rs:1618 / 681 / 632 / 1010)
//   Position::as_index                      (entity.rs:580-581)
//   EntityType::is_tower2 (entity.rs:1308-1309) -> TowerType::is_second_tower (tower.rs:99-100)
//   map_regions::is_top_side                (map_regions.rs:21-24)

// --- :135  tower = game.tower(line, team)
assert!(team < 2);                        // 아니면 panic_bounds_check(len=2)
let (a, b) = match line {                 // 다른 값이면 unreachable
  Top    => (game.top_tower,    game.top_tower2),      // 0x180 / 0x190
  Mid    => (game.mid_tower,    game.mid_tower2),      // 0x1a0 / 0x1b0
  Bottom => (game.bottom_tower, game.bottom_tower2),   // 0x1c0 / 0x1d0
};
let tower: Option<&Entity> = a[team].or(b[team]);      // 1차 우선, None 이면 2차

// --- :136  타워가 아예 없으면 라인·팀 고정 부시로 조기 반환
if tower.is_none() {
  return match line {                     // :137
    Top    => if team == 0 { 2 } else { 16 },   // :138
    Mid    => if team == 0 { 4 } else { 17 },   // :139
    Bottom => if team == 0 { 9 } else { 21 },   // :140
  };
}

let tower = tower.unwrap();               // :144 (Some 확정 — 코드 안 생김)
// --- :145  내 챔피언 (None 이면 Option::unwrap_failed 패닉)
let champ = game.player_champion[team][player.info.position.as_index()].unwrap();
//          주소 = game + 0x1e0 + team*40 + pos*8

let is_tower = (tower.ty_tag == 2);            // 0x68, EntityType::Tower
let is_2nd   = (tower.tower_ty > 4);           // 0x128, Top2/Mid2/Bottom2
let top_side = (context.setting.height - champ.y) < champ.x;  // is_top_side, 팀 무관 절대좌표

// --- :147  match line
match line {

 Top => {                                      // :149  let Tower(info) = tower.ty else { panic!() @:160 }
   if !is_tower { panic(@:160); }
   if is_2nd {                                  // :150
     if team == 0 { 3 } else { 6 }              // :151
   } else if info.nearest_enemy.is_some() {     // :153  (0x88 태그 != 0)
     if team == 0 { 6 } else { 3 }              // :154   <- 값 반전
   } else {
     if team == 0 { 3 } else { 6 }              // :156
   }
 }

 Mid => {                                      // :164  tower.ty.is_tower2()  (= is_tower && is_2nd)
   if is_tower && is_2nd {
     // :165  여기서만 팀 구분이 살아있다
     if top_side { if team == 0 { 13 } else { 18 } }   // :168
     else        { if team == 0 {  8 } else { 12 } }   // :166
   } else {
     // :171  팀 무관 — 2차타워가 아니거나 타워 엔티티가 아니면 이 경로
     if top_side { 14 } else { 11 }
   }
 }

 Bottom => {                                   // :179  let Tower(info) = tower.ty else { panic!() @:190 }
   if !is_tower { panic(@:190); }
   if is_2nd {                                  // :180
     if team == 0 { 15 } else { 20 }            // :181
   } else if info.nearest_enemy.is_some() {     // :183
     if team == 0 { 20 } else { 15 }            // :184   <- 값 반전
   } else {
     if team == 0 { 15 } else { 20 }            // :186
   }
 }
}

// 구조 관찰
// 1) Top/Bottom 은 완전 대칭(3/6 <-> 15/20)이고 부시 후보가 2개뿐이다. 결정 요인은
//    nearest_enemy 유무 하나이며 그것이 두 부시를 서로 맞바꾼다(2차 타워면 무조건 기본쪽).
// 2) Mid 만 좌표 기반(is_top_side)으로 갈리고 후보가 6개(8/11/12/13/14/18)다.
// 3) Top/Bottom 은 타워 엔티티가 Tower 변형이 아니면 패닉하지만, Mid 는 is_tower2() 가
//    false 를 돌려 :171 로 흘러간다 — 비대칭.
// 4) champ 는 Mid 경로에서만 실제로 쓰이지만 unwrap 은 :145 에서 무조건 실행된다
//    (= 내 포지션의 챔피언이 없으면 어느 라인이든 패닉).
// 5) 반환 phi 는 12갈래이고 값이 전부 다르다 = 12개 서로 다른 판정 결과.
